// Voice-over playback (v1.1) — pre-recorded edge-tts clips only, zero speechSynthesis (owner: fx-audio).
// Manifest: src/data/voice_lines.js, generated by tools/gen_voice.py from its single line list (assets/voice/*.mp3).
//
// - One voice channel: a new line cancels the one playing; follow-ups ('queue') wait for it to finish (bounded by
//   maxWait, then they cut in) and low-priority chatter ('ifIdle') is skipped while someone is talking.
// - Clips are fetched lazily (plus a gentle background prefetch), decoded ONCE with the shared WebAudio context from
//   audio.js (unlocked on the first user gesture) and kept in a small LRU of decoded buffers.
// - While a line plays the BGM ducks -6 dB and the English subtitle shows (>= 20 px, auto-hides, steers clear of
//   buttons/trays).
// - On/off lives in the pause menu next to Music/Sounds (persisted by the UI in `pageant_progress`.voiceOff).
// - Never throws and never blocks gameplay: a missing/undecodable clip just counts as failed. state.stats.voice counts
//   logical line requests deterministically (like stats.sounds), so stepFrames sims and F11 determinism hold.
import { VOICE_BASE, VOICE_LINES } from '../data/voice_lines.js';

const CONTESTANTS = Object.freeze([
  'sheep', 'slime', 'cat', 'golem', 'snow', 'creeper', 'bee', 'ender', 'wither', 'villager', 'dragon', 'pinksheep',
]);
const TIER_IDS = Object.freeze(['perfect', 'gorgeous', 'pretty', 'okay', 'tryhard']);

// Shared tier reactions per personality group; per-contestant playback tint keeps them sounding like her.
export const TIER_GROUP = Object.freeze({
  sheep: 'sweet', cat: 'sweet', bee: 'sweet', pinksheep: 'sweet',
  slime: 'bouncy', snow: 'bouncy', creeper: 'bouncy',
  golem: 'cool', ender: 'cool', villager: 'cool',
  wither: 'spooky', dragon: 'spooky',
});
export const VOICE_TINT = Object.freeze({
  sheep: 1.0, cat: 0.97, bee: 1.07, pinksheep: 1.05,
  slime: 1.0, snow: 0.98, creeper: 0.95,
  golem: 0.92, ender: 1.0, villager: 1.03,
  wither: 1.0, dragon: 1.05,
});

// gag event id -> voice line (gags not listed are voiced by the contestant's quest-complete cheer)
export const GAG_LINES = Object.freeze({
  kai_bounced: 'kai_bounced',
  cat_gift_kai_hat: 'kai_hat',
  kai_hogs_pumpkins: 'kai_pumpkins',
  fake_iron: 'bella_nose',
  snow_head_pop: 'snowgolem_pop',
  kai_snowman: 'kai_snowman',
  kai_honey: 'kai_honey',
  kai_steal: 'kai_steal',
  kai_cake_face: 'kai_cake',
  skeleton_bald: 'skel_bald',
  kai_faint: 'kai_faint',
  egg_hop: 'dragon_hop',
  pink_dye: 'bella_pink',
});

const NARRATOR_IDS = Object.freeze([
  'narr_welcome', 'narr_welcome_back', 'narr_booth', 'narr_booth2', 'narr_board', 'narr_board2', 'narr_next',
  'narr_hidden', 'narr_finale', 'narr_results', 'narr_end', 'narr_nether',
]);

// Every line id the triggers below can request (E2E: each must exist in the manifest and decode).
export const REFERENCED_VOICE_IDS = Object.freeze([
  ...new Set([
    ...NARRATOR_IDS,
    ...CONTESTANTS.flatMap((c) => [`${c}_intro`, `${c}_hint`, `${c}_cheer`]),
    ...['sweet', 'bouncy', 'cool', 'spooky'].flatMap((g) => TIER_IDS.map((t) => `${g}_${t}`)),
    ...TIER_IDS.map((t) => `kai_r_${t}`),
    ...Object.values(GAG_LINES),
    'kai_finale',
    'mrq_diamonds',
  ]),
]);

const DECODED_CAP = 32; // LRU of decoded AudioBuffers (~3 s mono each)
const LOCKED_WAIT_MS = 1400; // a line requested in the same gesture that unlocks audio still plays
const STALE_MS = 4000; // a line whose clip arrives later than this is dropped (no late chatter)
const PREFETCH_CONCURRENCY = 2;

const nowMs = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());

export function createVoice(ctx = {}, { enabled: initialEnabled = true } = {}) {
  let enabled = Boolean(initialEnabled);
  const bytes = new Map(); // id -> Promise<ArrayBuffer>
  const decoded = new Map(); // id -> AudioBuffer (insertion order = LRU)
  const failedIds = new Set();
  const info = { requested: 0, played: 0, failed: 0, skipped: 0, dropped: 0, decoded: 0, lastId: null };
  const history = []; // last 40 channel events { id, ev: req|queue|skip|play|cut|drop, t (ms) } for debugging/tests
  const log = (id, ev) => {
    history.push({ id, ev, t: Math.round(nowMs()) });
    if (history.length > 40) history.shift();
  };

  let playToken = 0;
  let current = null; // { id, token, ended, src, startedAt }
  const queue = []; // [{ id, rate, queuedAt, maxWait, timer }]
  let prefetchStarted = false;

  // Per-run trigger memory (reset on every new game)
  let introduced = new Set();
  let seenOnce = new Set();
  let boothCount = 0;
  let boardCount = 0;
  let nextCount = 0;
  let lastRankSig = '';
  let prevScene = 'title';

  // ---------------------------------------------------------------------------------------------------------
  // Subtitle (English, big, auto-hide; pointer-events none; placed clear of buttons, trays and the HUD strip)
  // ---------------------------------------------------------------------------------------------------------
  let subEl = null;
  let subText = null;
  let hideTimer = 0;
  let placeTimer = 0;
  if (typeof document !== 'undefined' && document.body) {
    subEl = document.createElement('div');
    subEl.id = 'voice-subtitle';
    subEl.className = 'voice-subtitle ui-hidden';
    subEl.hidden = true;
    subEl.setAttribute('role', 'status');
    subEl.setAttribute('aria-live', 'polite');
    subText = document.createElement('span');
    subText.className = 'voice-subtitle-text';
    subEl.appendChild(subText);
    document.body.appendChild(subEl);
    window.addEventListener('resize', () => {
      if (subEl && !subEl.hidden) placeSubtitle();
    });
  }

  // Present on screen (opacity ignored on purpose: a tray that is still fading in is about to be there).
  function isShown(el) {
    if (!el || el === subEl || el.hasAttribute?.('hidden')) return false;
    let cur = el;
    while (cur && cur !== document.documentElement) {
      if (cur.hasAttribute?.('hidden')) return false;
      const cs = window.getComputedStyle(cur);
      if (cs.display === 'none' || cs.visibility === 'hidden') return false;
      cur = cur.parentElement;
    }
    const r = el.getBoundingClientRect();
    return r.width > 1 && r.height > 1;
  }

  function obstacleRects() {
    const sel = 'button, [role="button"], [data-draggable="true"], #hud-objective, .booth-tray, .board-tray';
    const out = [];
    for (const el of document.querySelectorAll(sel)) {
      if (subEl.contains(el) || !isShown(el)) continue;
      out.push(el.getBoundingClientRect());
    }
    return out;
  }

  const overlaps = (a, b, pad = 6) =>
    a.left < b.right + pad && a.right > b.left - pad && a.top < b.bottom + pad && a.bottom > b.top - pad;

  // Pick the first free spot for the subtitle: low on screen (centred, then left- or right-aligned), stepping up
  // above bottom trays/buttons, then just under the top HUD row; if nothing is free, the least-covered spot.
  function placeSubtitle() {
    if (!subEl) return;
    const vw = window.innerWidth || 1280;
    const vh = window.innerHeight || 800;
    const margin = 14;
    subEl.style.left = '';
    subEl.style.top = '';
    subEl.style.bottom = '';
    subEl.style.transform = '';
    const box = subEl.getBoundingClientRect();
    const w = box.width;
    const h = box.height;
    if (!(w > 1 && h > 1)) return;
    const obstacles = obstacleRects();
    const base = vh < 520 ? 10 : 18;
    const tops = [vh - base - h];
    for (const o of [...obstacles].sort((a, b) => b.top - a.top)) {
      if (o.top > vh * 0.35) tops.push(o.top - 10 - h);
    }
    const topRow = obstacles.filter((o) => o.top < vh * 0.3).reduce((m, o) => Math.max(m, o.bottom), 0);
    tops.push(topRow + 10);
    const lefts = [(vw - w) / 2, margin, vw - margin - w];
    let best = null;
    for (const top of tops) {
      if (top < 0 || top + h > vh) continue;
      for (const left of lefts) {
        if (left < 0 || left + w > vw) continue;
        const r = { left, top, right: left + w, bottom: top + h };
        let cover = 0;
        for (const o of obstacles) {
          if (!overlaps(o, r)) continue;
          cover += (Math.min(o.right, r.right) - Math.max(o.left, r.left) + 12) *
            (Math.min(o.bottom, r.bottom) - Math.max(o.top, r.top) + 12);
        }
        if (cover === 0) {
          best = { left, top, cover };
          break;
        }
        if (!best || cover < best.cover) best = { left, top, cover };
      }
      if (best && best.cover === 0) break;
    }
    if (!best) return;
    subEl.style.transform = 'none';
    subEl.style.bottom = 'auto';
    subEl.style.left = `${Math.round(best.left)}px`;
    subEl.style.top = `${Math.round(best.top)}px`;
  }

  function showSubtitle(text, seconds) {
    if (!subEl) return;
    clearTimeout(hideTimer);
    subText.textContent = text;
    subEl.hidden = false;
    subEl.classList.remove('ui-hidden');
    placeSubtitle();
    // Trays / cards appear after a scene change: keep re-checking placement (5 Hz) while the line shows.
    clearInterval(placeTimer);
    placeTimer = setInterval(placeSubtitle, 200);
    hideTimer = setTimeout(hideSubtitle, Math.max(900, seconds * 1000 + 450));
  }

  function hideSubtitle() {
    if (!subEl) return;
    clearTimeout(hideTimer);
    clearInterval(placeTimer);
    subEl.hidden = true;
    subEl.classList.add('ui-hidden');
  }

  // ---------------------------------------------------------------------------------------------------------
  // Loading / decoding (decode once, LRU-capped)
  // ---------------------------------------------------------------------------------------------------------
  function getAC() {
    try {
      return ctx.audio?.getContext?.() || null;
    } catch (_) {
      return null;
    }
  }

  function fetchBytes(id) {
    if (bytes.has(id)) return bytes.get(id);
    const line = VOICE_LINES[id];
    const p = (line && typeof fetch === 'function'
      ? fetch(VOICE_BASE + line.file).then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(new Error(`HTTP ${r.status}`))))
      : Promise.reject(new Error('no fetch'))
    );
    p.catch(() => {
      bytes.delete(id);
      if (!failedIds.has(id)) {
        failedIds.add(id);
        info.failed += 1;
      }
    });
    bytes.set(id, p);
    return p;
  }

  function decodeWith(ac, buf) {
    return new Promise((resolve, reject) => {
      try {
        const ret = ac.decodeAudioData(buf, resolve, reject);
        if (ret && typeof ret.then === 'function') ret.then(resolve, reject);
      } catch (e) {
        reject(e);
      }
    });
  }

  async function getBuffer(id, ac) {
    const hit = decoded.get(id);
    if (hit) {
      decoded.delete(id);
      decoded.set(id, hit);
      return hit;
    }
    const raw = await fetchBytes(id);
    const audioBuf = await decodeWith(ac, raw.slice(0));
    decoded.set(id, audioBuf);
    info.decoded += 1;
    while (decoded.size > DECODED_CAP) decoded.delete(decoded.keys().next().value);
    return audioBuf;
  }

  function prefetch(ids) {
    for (const id of ids) {
      if (VOICE_LINES[id] && !failedIds.has(id)) fetchBytes(id).catch(() => {});
    }
  }

  // Gentle background trickle of every clip's bytes (~2 MB total) once audio is live, so later lines start instantly.
  function startBackgroundPrefetch() {
    if (prefetchStarted) return;
    prefetchStarted = true;
    const ids = Object.keys(VOICE_LINES).filter((id) => !bytes.has(id));
    let i = 0;
    const pump = () => {
      if (i >= ids.length) return;
      const id = ids[i++];
      fetchBytes(id).catch(() => {}).finally(() => setTimeout(pump, 120));
    };
    for (let k = 0; k < PREFETCH_CONCURRENCY; k++) setTimeout(pump, 2500 + k * 300);
  }

  function waitRunning(ac, ms) {
    if (ac.state === 'running') return Promise.resolve(true);
    return new Promise((resolve) => {
      let done = false;
      let timer = 0;
      const onChange = () => {
        if (ac.state === 'running') finish(true);
      };
      const finish = (v) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        try {
          ac.removeEventListener('statechange', onChange);
        } catch (_) {}
        resolve(v);
      };
      try {
        ac.addEventListener('statechange', onChange);
      } catch (_) {}
      timer = setTimeout(() => finish(ac.state === 'running'), ms);
    });
  }

  // ---------------------------------------------------------------------------------------------------------
  // Channel
  // ---------------------------------------------------------------------------------------------------------
  function stopCurrent() {
    if (!current) return;
    const c = current;
    current = null;
    if (!c.ended && c.src && c.endedNaturally !== true) log(c.id, 'cut');
    c.ended = true;
    if (c.src) {
      c.src.onended = null;
      try {
        c.src.stop();
      } catch (_) {}
      try {
        c.src.disconnect();
      } catch (_) {}
    }
  }

  function finish(token) {
    if (!current || current.token !== token) return;
    stopCurrent();
    ctx.audio?.duckMusic?.(false);
    hideSubtitle();
    drainQueue();
  }

  function drainQueue() {
    while (queue.length > 0) {
      const item = queue.shift();
      clearTimeout(item.timer);
      if (nowMs() - item.queuedAt <= item.maxWait * 1000 + STALE_MS) {
        playNow(item);
        return;
      }
      info.dropped += 1;
      log(item.id, 'drop');
    }
  }

  async function playNow(item) {
    stopCurrent();
    const token = ++playToken;
    const attemptAt = nowMs();
    current = { id: item.id, token, ended: false, src: null, startedAt: 0 };
    const ac = getAC();
    if (!ac || !enabled) {
      info.dropped += 1;
      finish(token);
      return;
    }
    let buf = null;
    try {
      buf = await getBuffer(item.id, ac);
    } catch (_) {
      if (!failedIds.has(item.id)) {
        failedIds.add(item.id);
        info.failed += 1;
      }
    }
    if (!current || current.token !== token) return; // superseded while loading
    if (!buf || !enabled || nowMs() - attemptAt > STALE_MS) {
      if (buf) info.dropped += 1;
      finish(token);
      return;
    }
    if (ac.state !== 'running') {
      const live = await waitRunning(ac, LOCKED_WAIT_MS);
      if (!current || current.token !== token) return;
      if (!live) {
        info.dropped += 1;
        finish(token);
        return;
      }
    }
    try {
      const bus = ctx.audio?.getVoiceBus?.() || ac.destination;
      const src = ac.createBufferSource();
      src.buffer = buf;
      src.playbackRate.value = item.rate || 1;
      src.connect(bus);
      src.onended = () => {
        if (current && current.token === token) current.endedNaturally = true;
        finish(token);
      };
      src.start();
      log(item.id, 'play');
      current.src = src;
      current.startedAt = nowMs();
      info.played += 1;
      info.lastId = item.id;
      ctx.audio?.duckMusic?.(true);
      showSubtitle(item.text, buf.duration / (item.rate || 1));
      startBackgroundPrefetch();
    } catch (_) {
      info.failed += 1;
      finish(token);
    }
  }

  function bumpStat() {
    const st = ctx.state?.stats;
    if (st) st.voice = (st.voice | 0) + 1;
  }

  // Request a line. mode: 'cancel' (default) | 'queue' (wait for the current line, up to maxWait s) | 'ifIdle'.
  // defer: decide after the current event dispatch finishes (e.g. the booth narration must queue behind the
  // quest-complete cheer that the same questComplete dispatch requests a moment later). Stats stay synchronous.
  function say(id, { mode = 'cancel', rate = 1, maxWait = 3, defer = false } = {}) {
    try {
      const line = VOICE_LINES[id];
      if (!line) return false;
      bumpStat();
      info.requested += 1;
      if (!enabled) return false;
      if (defer) {
        queueMicrotask(() => channel(id, line, { mode, rate, maxWait }));
        return true;
      }
      return channel(id, line, { mode, rate, maxWait });
    } catch (_) {
      return false;
    }
  }

  function channel(id, line, { mode, rate, maxWait }) {
    try {
      if (!enabled) return false;
      const item = { id, text: line.text, rate, maxWait, queuedAt: nowMs(), timer: 0 };
      const busy = Boolean(current && !current.ended);
      if (busy && mode === 'ifIdle') {
        info.skipped += 1;
        log(id, 'skip');
        return false;
      }
      log(id, busy && mode === 'queue' ? 'queue' : 'req');
      if (busy && mode === 'queue') {
        if (queue.length >= 3) queue.shift();
        queue.push(item);
        item.timer = setTimeout(() => {
          const idx = queue.indexOf(item);
          if (idx >= 0) {
            queue.splice(idx, 1);
            playNow(item); // waited long enough: cut in
          }
        }, Math.max(0, maxWait) * 1000);
        return true;
      }
      for (const q of queue.splice(0)) clearTimeout(q.timer);
      playNow(item);
      return true;
    } catch (_) {
      return false;
    }
  }

  function stop() {
    for (const q of queue.splice(0)) clearTimeout(q.timer);
    if (current) {
      stopCurrent();
      ctx.audio?.duckMusic?.(false);
    }
    hideSubtitle();
  }

  function setEnabled(b) {
    enabled = Boolean(b);
    if (!enabled) stop();
    return enabled;
  }

  // New run (title ▶ / continue / replay): reset trigger memory and greet.
  function onGameStart({ resume = false } = {}) {
    stop();
    introduced = new Set();
    seenOnce = new Set();
    boothCount = 0;
    boardCount = 0;
    nextCount = 0;
    lastRankSig = '';
    prevScene = 'world';
    say(resume ? 'narr_welcome_back' : 'narr_welcome');
    prefetch(['sheep_intro', 'sheep_hint', 'narr_welcome_back']);
  }

  function once(key) {
    if (seenOnce.has(key)) return false;
    seenOnce.add(key);
    return true;
  }

  // ---------------------------------------------------------------------------------------------------------
  // Triggers (§3.2 events — modules emit, voice listens)
  // ---------------------------------------------------------------------------------------------------------
  const ev = ctx.events;
  if (ev && typeof ev.on === 'function') {
    ev.on('questStart', (p) => {
      const cid = p?.contestantId || p?.id;
      if (!cid || !VOICE_LINES[`${cid}_intro`]) return;
      if (!introduced.has(cid)) {
        introduced.add(cid);
        say(`${cid}_intro`, { mode: 'queue', maxWait: 3 });
        say(`${cid}_hint`, { mode: 'queue', maxWait: 7 });
      } else {
        say(`${cid}_hint`, { mode: 'ifIdle' });
      }
      const group = TIER_GROUP[cid];
      prefetch([`${cid}_cheer`, 'narr_booth', 'narr_board', ...TIER_IDS.map((t) => `${group}_${t}`)]);
    });

    ev.on('questComplete', (p) => {
      const cid = p?.contestantId || p?.id;
      if (!cid) return;
      say(`${cid}_cheer`, { mode: 'queue', maxWait: 1.6 });
      if (p?.hidden) say('narr_hidden', { mode: 'queue', maxWait: 6 });
    });

    ev.on('gag', (p) => {
      const lid = GAG_LINES[p?.gagId];
      if (!lid) return;
      say(lid, { mode: once(`gag:${p.gagId}`) ? 'cancel' : 'ifIdle' });
    });

    ev.on('collect', (p) => {
      if (p?.item === 'diamond' && once('mrq')) say('mrq_diamonds', { mode: 'queue', maxWait: 2 });
    });

    ev.on('boothStart', () => {
      boothCount += 1;
      if (boothCount <= 2) say('narr_booth', { mode: 'queue', maxWait: 4.5, defer: true });
      else if (boothCount % 2 === 1) say('narr_booth2', { mode: 'queue', maxWait: 4.5, defer: true });
    });

    ev.on('sceneChange', (p) => {
      const scene = p?.scene || p;
      if (scene === 'board' && p?.mode === 'rank' && p?.newId && p.newId !== 'kai') {
        boardCount += 1;
        // The booth is over once the board opens: its narration yields at once; anything else (a cheer) may finish.
        const boothTalk = Boolean(current && !current.ended && String(current.id).startsWith('narr_booth'));
        if (boardCount <= 2) say('narr_board', { mode: boothTalk ? 'cancel' : 'queue', maxWait: 3 });
        else if (boardCount % 3 === 0) say('narr_board2', { mode: boothTalk ? 'cancel' : 'ifIdle' });
        else if (boothTalk) stop();
      } else if (scene === 'world' && prevScene === 'board' && ctx.quests?.next?.()) {
        nextCount += 1;
        if (nextCount <= 3) say('narr_next', { mode: 'ifIdle' });
      } else if (scene === 'final' && prevScene !== 'final') {
        say('narr_results', { mode: 'queue', maxWait: 3 });
      }
      if (typeof scene === 'string') prevScene = scene;
      // A line that spans a scene change re-docks clear of the new scene's trays/cards right away.
      if (subEl && !subEl.hidden) setTimeout(placeSubtitle, 0);
    });

    ev.on('rank', (p) => {
      const id = p?.id;
      const tier = p?.tier;
      if (!id || !TIER_IDS.includes(tier)) return;
      const sig = `${id}:${tier}:${ctx.frame ?? ctx.state?.frame ?? 0}`;
      if (sig === lastRankSig) return; // same drop echoed through UI + core in one frame
      lastRankSig = sig;
      if (id === 'kai') {
        say(`kai_r_${tier}`);
      } else {
        say(`${TIER_GROUP[id] || 'sweet'}_${tier}`, { rate: VOICE_TINT[id] || 1 });
      }
    });

    ev.on('finaleStart', () => {
      say('narr_finale');
      say('kai_finale', { mode: 'queue', maxWait: 3.5 });
      prefetch(TIER_IDS.map((t) => `kai_r_${t}`).concat(['narr_results']));
    });

    ev.on('areaChange', (p) => {
      const area = p?.area;
      if ((area === 'end' || area === 'nether') && once(`area:${area}`)) {
        say(area === 'end' ? 'narr_end' : 'narr_nether', { mode: 'queue', maxWait: 2.5 });
      }
    });
  }

  // Test/agent helper: fetch + decode every manifest clip (OfflineAudioContext needs no user gesture).
  async function verifyAll(ids = Object.keys(VOICE_LINES)) {
    const OAC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    const ac = getAC() || (OAC ? new OAC(1, 1, 24000) : null);
    const out = { checked: 0, ok: 0, failed: [], totalSec: 0 };
    if (!ac) return { ...out, failed: ['no-audio-context'] };
    for (const id of ids) {
      out.checked += 1;
      try {
        const line = VOICE_LINES[id];
        if (!line) throw new Error('not in manifest');
        const raw = await fetchBytes(id);
        const b = await decodeWith(ac, raw.slice(0));
        if (!(b.duration > 0.3)) throw new Error('empty');
        out.ok += 1;
        out.totalSec += b.duration;
      } catch (e) {
        out.failed.push(`${id}: ${e?.message || e}`);
      }
    }
    out.totalSec = Math.round(out.totalSec * 10) / 10;
    return out;
  }

  function getInfo() {
    const ac = getAC();
    return {
      enabled,
      unlocked: Boolean(ac && ac.state === 'running'),
      lines: Object.keys(VOICE_LINES).length,
      referenced: REFERENCED_VOICE_IDS.length,
      requested: info.requested,
      played: info.played,
      failed: info.failed,
      skipped: info.skipped,
      dropped: info.dropped,
      decoded: info.decoded,
      cachedBytes: bytes.size,
      lastId: info.lastId,
      currentId: current && !current.ended ? current.id : null,
      queued: queue.map((q) => q.id),
      history: history.map((h) => ({ ...h })),
      musicDucked: Boolean(ctx.audio?.isMusicDucked?.()),
      subtitle: {
        visible: Boolean(subEl && !subEl.hidden),
        text: subEl && !subEl.hidden ? subText.textContent : '',
      },
    };
  }

  return {
    say,
    stop,
    setEnabled,
    isEnabled: () => enabled,
    onGameStart,
    prefetch,
    verifyAll,
    info: getInfo,
    referencedIds: () => [...REFERENCED_VOICE_IDS],
    lineIds: () => Object.keys(VOICE_LINES),
    placeSubtitle,
  };
}

export default createVoice;
